-- Generated by scripts/places (MileSplit Live finals). Inserts MeetPlacings (Place, 0 points, no participant) only where the performance has none. Id-independent; re-runnable.
SET QUOTED_IDENTIFIER ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @pid INT;

-- 2023 Akron Rubber City HS Open: Presly McConnell Shot Put place 7
SET @pid = (SELECT TOP 1 p.Id FROM Performances p JOIN Athletes a ON a.Id=p.AthleteId JOIN Meets m ON m.Id=p.MeetId JOIN Events e ON e.Id=p.EventId WHERE a.FirstName+N' '+a.LastName=N'Presly McConnell' AND a.Gender=2 AND m.Name=N'2023 Akron Rubber City HS Open' AND CAST(m.Date AS date)='2023-02-18' AND e.Name=N'Shot Put' AND e.Gender=2);
IF @pid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM MeetPlacings WHERE PerformanceId=@pid) INSERT INTO MeetPlacings (MeetId, PerformanceId, MeetParticipantId, Place, FullPoints, SplitPoints) SELECT MeetId, Id, NULL, 7, 0, 0 FROM Performances WHERE Id=@pid;
-- 2023 Akron Rubber City HS Open: Royce Zirkle Shot Put place 15
SET @pid = (SELECT TOP 1 p.Id FROM Performances p JOIN Athletes a ON a.Id=p.AthleteId JOIN Meets m ON m.Id=p.MeetId JOIN Events e ON e.Id=p.EventId WHERE a.FirstName+N' '+a.LastName=N'Royce Zirkle' AND a.Gender=1 AND m.Name=N'2023 Akron Rubber City HS Open' AND CAST(m.Date AS date)='2023-02-18' AND e.Name=N'Shot Put' AND e.Gender=1);
IF @pid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM MeetPlacings WHERE PerformanceId=@pid) INSERT INTO MeetPlacings (MeetId, PerformanceId, MeetParticipantId, Place, FullPoints, SplitPoints) SELECT MeetId, Id, NULL, 15, 0, 0 FROM Performances WHERE Id=@pid;
-- 2023 Tom Fasko Medina Relays: relay 4x1600M Relay place 6
SET @pid = (SELECT MIN(p.Id) FROM Performances p JOIN Meets m ON m.Id=p.MeetId JOIN Events e ON e.Id=p.EventId WHERE p.AthleteId IS NULL AND m.Name=N'2023 Tom Fasko Medina Relays' AND CAST(m.Date AS date)='2023-04-08' AND e.Name=N'4x1600M Relay' AND e.Gender=1 AND ABS(p.TimeSeconds-1177.22)<0.06);
